export function icon(name, slot = '') {
  const key = Object.hasOwn(symbols, name) ? name : 'help';
  return `<svg class="icon icon-${key}" ${slot ? `slot="${slot}"` : ''} viewBox="${viewBoxes[key]}" fill="currentColor" aria-hidden="true" focusable="false">${symbols[key]}</svg>`;
}
